import React from 'react';
import { useState } from 'react';
import { Row, Col } from 'reactstrap';
import CustomInput from 'views/admin/Common/CustomInput';
import CustomButton from 'components/CustomButton';
import { formResMessage, getGlobalSchoolUtils, getLocalStore } from 'utils/commonFunc';
import CustomSelect from 'components/CustomSelect';
import { Paper } from '@material-ui/core';
import { saveCourseCodeApi, saveSubjectCodeApi } from 'actions/admin/config';
import { useSelector } from 'react-redux';

const initialState = {
  code: '',
  name: '',
  schoolId: 0,
  studyLevel: '',
  classLevel: '',
  section: '',
};

// Fixed LKG -> 12th progression used when creating a class (formFor "showCourseForm").
// The admin only ever picks a class + names a section ("A", "BIO", ...) - code and
// studyLevel are derived from this list, never typed by hand, matching the naming
// convention the school's own data already uses (e.g. "TAN_LKG_A" / "LKG - Section A").
const CLASS_LEVELS = [
  { value: 'PRELKG', label: 'PRE LKG', studyLevel: 'PRIMARY' },
  { value: 'LKG', label: 'LKG', studyLevel: 'PRIMARY' },
  { value: 'UKG', label: 'UKG', studyLevel: 'PRIMARY' },
  { value: '01', label: '1st Standard', studyLevel: 'PRIMARY' },
  { value: '02', label: '2nd Standard', studyLevel: 'PRIMARY' },
  { value: '03', label: '3rd Standard', studyLevel: 'PRIMARY' },
  { value: '04', label: '4th Standard', studyLevel: 'PRIMARY' },
  { value: '05', label: '5th Standard', studyLevel: 'PRIMARY' },
  { value: '06', label: '6th Standard', studyLevel: 'SECONDARY' },
  { value: '07', label: '7th Standard', studyLevel: 'SECONDARY' },
  { value: '08', label: '8th Standard', studyLevel: 'SECONDARY' },
  { value: '09', label: '9th Standard', studyLevel: 'SECONDARY' },
  { value: '10', label: '10th Standard', studyLevel: 'SECONDARY' },
  { value: '11', label: '11th Standard', studyLevel: 'HIGHER_SECONDARY' },
  { value: '12', label: '12th Standard', studyLevel: 'HIGHER_SECONDARY' },
];

const CourseOrSubjectCodeForm = ({ isShow, formFor, codeList, hideForm, toggleLoading, updateSuccess }) => {
  const isCourseForm = formFor === 'showCourseForm';
  const [loading, setLoading] = useState(false);
  const [state, setState] = useState(initialState);
  const [errors, setError] = useState({});
  const [globalError, setGlobalError] = useState('');
  const authStore = useSelector(storeState => storeState?.auth);

  const closeForm = () => {
    setState(initialState);
    setError({});
    setLoading(false);
    hideForm();
  };

  const handleChange = (name, value) => {
    setState(prevState => ({
      ...prevState,
      [name]: value,
    }));
  };

  const handleClassLevelChange = (name, value) => {
    const level = CLASS_LEVELS.find(el => el.value === value);
    setState(prevState => ({
      ...prevState,
      classLevel: value,
      studyLevel: level?.studyLevel || '',
    }));
  };

  const isExists = (list, passCode) => {
    return list.find(el => el.code === passCode);
  };

  // For a class, code/name are generated from classLevel + section rather than typed -
  // this builds the same shape the rest of the form (validate/submit) already expects.
  const buildCourseFields = () => {
    const globalSchool = getGlobalSchoolUtils();
    const level = CLASS_LEVELS.find(el => el.value === state.classLevel);
    const section = state.section?.trim().toUpperCase();
    const prefix = (globalSchool?.schoolCode || '').split('_')[0] || 'SCH';
    return {
      code: level && section ? `${prefix}_${level.value}_${section}` : '',
      name: level && section ? `${level.label} - Section ${section}` : '',
      studyLevel: level?.studyLevel || '',
    };
  };

  const validateForm = data => {
    const errors = {};
    if (isCourseForm) {
      if (!state.classLevel) {
        errors['classLevel'] = 'Class cannot be empty';
      }
      if (!state.section?.trim()) {
        errors['section'] = 'Section cannot be empty';
      }
      if (data?.code && isExists(codeList, data.code)) {
        errors['section'] = 'This class + section already exists';
      }
      return errors;
    }
    if (!data?.code) {
      errors['code'] = 'Code cannot be empty';
    }
    if (data?.code && isExists(codeList, data.code)) {
      errors['code'] = 'Code already exists';
    }
    if (!data?.name) {
      errors['name'] = 'Name cannot be empty';
    }
    if (!data?.studyLevel) {
      errors['studyLevel'] = 'Study level cannot be empty';
    }
    return errors;
  };

  const handleSubmit = async e => {
    // No e.preventDefault() here - this form is rendered both standalone and nested
    // inside the Course/Subject creation modal's own <form>. It submits via an
    // explicit button onClick (type="button" below), never native form submission,
    // so there's no browser submit event to prevent and no nested-form conflict.
    const globalSchool = getGlobalSchoolUtils();
    const loggedUser = getLocalStore('loggedUser');
    const submitData = isCourseForm ? { ...state, ...buildCourseFields() } : state;
    const error = validateForm(submitData);
    setError(error);
    if (!Object.keys(error)?.length) {
      const postData = {
        postData: { ...submitData, schoolId: authStore?.loggedUserSchool || globalSchool?.schoolId },
        token: authStore?.loggedUserToken || loggedUser?.accessToken,
      };
      setLoading(true);
      toggleLoading(true);
      try {
        isCourseForm ? await saveCourseCodeApi(postData) : await saveSubjectCodeApi(postData);
        setLoading(false);
        toggleLoading(false);
        setGlobalError('');
        updateSuccess();
      } catch (err) {
        setLoading(false);
        setGlobalError(formResMessage(err));
      }
    }
  };

  //   PRIMARY (PRE_KG - 5th), SECONDARY (6th - 10th), HIGHER_SECONDARY (11th - 12th), DIPLOMO (Course), DEGREE (Graduate), GENERAL
  const studyLevels = [
    { label: 'PRIMARY (PRE_KG - 5th)', value: 'PRIMARY' },
    { label: 'SECONDARY (6th - 10th)', value: 'SECONDARY' },
    { label: 'HIGHER_SECONDARY (11th - 12th) (6th - 10th)', value: 'HIGHER_SECONDARY' },
    // { label: 'DIPLOMO (Course)', value: 'DIPLOMO' },
    // { label: 'DEGREE (Graduate)', value: 'DEGREE' },
    { label: 'GENERAL', value: 'GENERAL' },
  ];

  return isShow ? (
    <>
      <Paper variant="outlined" className="p-4">
        {globalError && <div className="error">{globalError}</div>}
        <div className="mt-1 mb-2">
          <Row>
            {isCourseForm ? (
              <>
                <Col md={4} sm={4} lg={4} xs={4}>
                  <CustomSelect
                    label="Class"
                    name="classLevel"
                    options={CLASS_LEVELS}
                    value={state.classLevel}
                    onChange={handleClassLevelChange}
                    usePortal
                    error={errors.classLevel}
                  />
                </Col>
                <Col md={4} sm={4} lg={4} xs={4}>
                  <CustomInput
                    label="Section"
                    name="section"
                    value={state.section}
                    onChange={handleChange}
                    placeholder="E.g: A"
                    error={errors.section}
                  />
                </Col>
              </>
            ) : (
              <>
                <Col md={4} sm={4} lg={4} xs={4}>
                  <CustomInput
                    label="Code"
                    name="code"
                    value={state.code}
                    onChange={handleChange}
                    error={errors.code}
                  />
                </Col>
                <Col md={4} sm={4} lg={4} xs={4}>
                  <CustomInput
                    label="Name"
                    name="name"
                    value={state.name}
                    onChange={handleChange}
                    error={errors.name}
                  />
                </Col>
                <Col md={4} sm={4} lg={4} xs={4}>
                  <CustomSelect
                    label="Study level"
                    name="studyLevel"
                    options={studyLevels}
                    value={state.studyLevel}
                    onChange={handleChange}
                    usePortal
                    error={errors.studyLevel}
                  />
                </Col>
              </>
            )}
          </Row>
          <div className="mt-2">
            <CustomButton
              type="button"
              size="small"
              name="Save"
              disabled={loading}
              loading={loading}
              onClick={handleSubmit}
            />
            <CustomButton
              className="ml-2"
              type="button"
              color="default"
              disabled={loading}
              onClick={closeForm}
              name="Cancel"
              size="small"
            />
          </div>
        </div>
      </Paper>
    </>
  ) : null;
};

export default CourseOrSubjectCodeForm;
